$('baseline').onclick=()=>{if(p.baselines.length>=10)return say('Maximum ten baselines per project.');let name=$('baselineName').value.trim()||'Design '+(p.baselines.length+1);edit(()=>{let project=clone(p);project.baselines=[];p.baselines.push({id:crypto.randomUUID(),name,time:new Date().toISOString(),project})},{geometry:false});$('baselineName').value='';say('Design baseline saved inside this project.')};$('compare').onclick=()=>{let b=p.baselines.find(b=>b.id===$('baselineSelect').value);if(!b)return say('Choose a saved baseline.');let current=new Map(p.objects.map(o=>[o.id,o])),old=new Map(b.project.objects.map(o=>[o.id,o])),added=[...current.keys()].filter(id=>!old.has(id)).length,removed=[...old.keys()].filter(id=>!current.has(id)).length,changed=[...current.keys()].filter(id=>old.has(id)&&JSON.stringify(old.get(id))!==JSON.stringify(current.get(id))).length,settings=['width','height','thickness','radius','mounting','bevel','kerf','precision'].filter(k=>p[k]!==b.project[k]);$('comparison').textContent=`Compared with ${b.name}:\n${added} added · ${removed} removed · ${changed} changed layers.\n${settings.length?'Changed settings: '+settings.join(', '):'Blank and fabrication settings unchanged.'}`};$('restoreBaseline').onclick=()=>{let b=p.baselines.find(b=>b.id===$('baselineSelect').value);if(!b)return say('Choose a saved baseline.');edit(()=>{let baselines=p.baselines;p=C.migrate(b.project);p.baselines=baselines;selected=[]});say('Baseline restored. Undo returns to the previous design.')};
