async function stackZip(project){let result=await request('stack',project),front=await request('build',project,{only2D:true}),zip=new JSZip();zip.file('01-front.svg',C.formatSVG(project,front.laser));zip.file('01-front.dxf',C.formatDXF(project,front.laser));for(let name of ['spacer','retainer']){zip.file(name+'-rear-MIRRORED.svg',C.formatSVG(project,result[name],{rear:true,label:name.toUpperCase()+' REAR — MIRRORED',mirror:true}));zip.file(name+'-rear-MIRRORED.dxf',C.formatDXF(project,result[name],true))}zip.file('ASSEMBLY.md',F.instructions(project));return zip.generateAsync({type:'uint8array',compression:'DEFLATE'})}$('laserStack').onclick=()=>exporting($('laserStack'),async()=>{download(await stackZip(clone(p)),F.slug(p.name)+'-laser-stack.zip','application/zip');say('Front, spacer and retainer files exported. Rear files are already mirrored; check registration before cutting.')});$('rearSvg').onclick=()=>{let circles=C.mounts(p).map(([x,y])=>C.roundedRect(p.magnetDiameter,p.magnetDiameter,p.magnetDiameter/2,p.precision).map(([X,Y])=>[X+x,Y+y]));download(C.formatSVG(p,{CUT:C.outline(p),POCKET_GUIDE:circles},{rear:true,label:'REAR POCKET GUIDE — MIRRORED',mirror:true}),F.slug(p.name)+'-rear-guide-MIRRORED.svg','image/svg+xml');say('Mirrored pocket guide exported; circles mark locations, not an automatic through-cut job.')};
$('bundle').onclick=()=>exporting($('bundle'),async()=>{let project=clone(p),result=await full(project),zip=new JSZip(),name=F.slug(project.name),inlays=project.objects.some(o=>o.inlay)?(await request('build',project,{insets:true,clearance:project.inlayClearance??.15})).insets:[];zip.file('print/'+name+'.stl',C.stl(result.mesh));zip.file('print/'+name+'.3mf',await F.threeMF(result.mesh,project,inlays));zip.file('laser/front.svg',C.formatSVG(project,result.laser));zip.file('laser/front.dxf',C.formatDXF(project,result.laser));if(project.width===156&&project.height===126.105){let stack=await request('stack',project);for(let kind of ['spacer','retainer']){zip.file('laser/'+kind+'-rear-MIRRORED.svg',C.formatSVG(project,stack[kind],{rear:true,label:kind.toUpperCase()+' REAR — MIRRORED',mirror:true}));zip.file('laser/'+kind+'-rear-MIRRORED.dxf',C.formatDXF(project,stack[kind],true))}}if(project.mounting!=='none'){let coupons=await request('build',project,{coupons:true});for(let part of coupons.coupons)zip.file('fit-coupons/'+part.name+'.stl',C.stl(part.mesh))}for(let[i,part]of inlays.entries())zip.file('inlays/'+(i+1)+'-'+F.slug(part.name)+'.stl',C.stl(part.mesh));if(project.stack?.length&&typeof stackZip==='function')zip.file('material-stack.zip',await stackZip(project));zip.file('project.json',JSON.stringify(project,null,2));zip.file('fabrication-sheet.html',F.report(project,result));zip.file('bill-of-materials.csv',F.bill(project));zip.file('ASSEMBLY.md',F.instructions(project));zip.file('manifest.json',JSON.stringify({application:'FACEBENCH',version:C.version,created:new Date().toISOString(),units:'mm',physicalFitVerified:false,mesh:{triangles:result.mesh.trianglesCount,components:result.mesh.components,volume:result.mesh.volume,bounds:result.mesh.bounds,status:result.mesh.status},findings:[...C.findings(project),...result.issues]},null,2));download(await zip.generateAsync({type:'uint8array',compression:'DEFLATE'}),name+'-manufacturing.zip','application/zip');say('Manufacturing package exported: print files, laser layers, coupons/inlays, project, fabrication sheet and assembly guide.')});
