$('importSvg').onclick=()=>$('svgFile').click();$('svgFile').onchange=async()=>{let file=$('svgFile').files[0];if(!file)return;try{let source=await file.text(),parsed=FaceSVG.importSVG(source,DOMParser,p.precision),w=Math.min(110,p.width*.75),h=w*parsed.sourceHeight/parsed.sourceWidth;if(h>p.height*.75){w*=p.height*.75/h;h=p.height*.75}let doc=new DOMParser().parseFromString(source,'image/svg+xml'),el=doc.documentElement,vb=(el.getAttribute('viewBox')||'').trim().split(/[\s,]+/).map(Number),mm=/^([\d.]+)mm$/.exec(el.getAttribute('width')||'');if(mm&&vb.length===4&&vb[2]>0){let natural=parsed.sourceWidth*Number(mm[1])/vb[2];if(natural<=p.width&&natural*parsed.sourceHeight/parsed.sourceWidth<=p.height){w=natural;h=w*parsed.sourceHeight/parsed.sourceWidth}}add('path',{name:file.name.replace(/\.svg$/i,''),w,h,contours:parsed.contours,parts:parsed.parts,fillRule:'NonZero'});say('SVG converted to local editable contours; no source scripts or linked resources were loaded.')}catch(e){say('SVG import failed: '+e.message)}$('svgFile').value=''};
$('image').onclick=()=>$('imageFile').click();$('imageFile').onchange=async()=>{let file=$('imageFile').files[0];if(!file)return;try{if(file.size>10e6||!['image/png','image/jpeg'].includes(file.type))throw Error('Choose a PNG/JPEG smaller than 10 MB.');let url=URL.createObjectURL(file),im=new Image();try{await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error('Image could not be decoded.'));im.src=url});let c=document.createElement('canvas'),scale=Math.min(1,128/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));let m=c.getContext('2d');m.fillStyle='white';m.fillRect(0,0,c.width,c.height);m.drawImage(im,0,0,c.width,c.height);let data=m.getImageData(0,0,c.width,c.height).data,pixels=[];for(let i=0;i<data.length;i+=4)pixels.push(Math.round(.2126*data[i]+.7152*data[i+1]+.0722*data[i+2]));add('image',{name:file.name,w:60,h:60*c.height/c.width,op:'engrave',depth:Math.min(.8,p.thickness-.5),data:c.toDataURL('image/png'),pixels,iw:c.width,ih:c.height,threshold:128});say('Image imported. Choose silhouette or grayscale relief and inspect it in 3D.')}finally{URL.revokeObjectURL(url)}}catch(e){say('Image import failed: '+e.message)}$('imageFile').value=''};
function flattenFontPath(commands){let paths=[],cur=[],x=0,y=0;for(let c of commands){if(c.type==='M'){cur=[[c.x,c.y]];x=c.x;y=c.y}else if(c.type==='L'){cur.push([c.x,c.y]);x=c.x;y=c.y}else if(c.type==='Q'||c.type==='C'){let sx=x,sy=y;for(let i=1;i<=12;i++){let t=i/12,u=1-t;if(c.type==='Q')cur.push([u*u*sx+2*u*t*c.x1+t*t*c.x,u*u*sy+2*u*t*c.y1+t*t*c.y]);else cur.push([u*u*u*sx+3*u*u*t*c.x1+3*u*t*t*c.x2+t*t*t*c.x,u*u*u*sy+3*u*u*t*c.y1+3*u*t*t*c.y2+t*t*t*c.y])}x=c.x;y=c.y}else if(c.type==='Z'){if(cur.length>=3)paths.push(cur);cur=[]}}return paths}
$('fontImport').onclick=()=>$('fontFile').click();$('fontFile').onchange=async()=>{let file=$('fontFile').files[0];if(!file)return;try{if(file.size>5e6)throw Error('Font exceeds 5 MB.');let font=opentype.parse(await file.arrayBuffer()),glyphs={},fontKey='custom-'+crypto.randomUUID();for(let i=32;i<256;i++){let ch=String.fromCharCode(i),g=font.charToGlyph(ch),commands=g.getPath(0,0,1).commands;glyphs[ch]={advance:g.advanceWidth/font.unitsPerEm,paths:flattenFontPath(commands)}}edit(()=>{p.customFonts[fontKey]={label:file.name.replace(/\.[^.]+$/,''),glyphs};if(object())object().font=fontKey});say('Font converted to local outlines and saved in the project. Respect its license when sharing designs.')}catch(e){say('Font import failed: '+e.message)}$('fontFile').value=''};
