(async function boot(){try{let savedPrefs=localStorage.getItem('facebench-prefs');if(savedPrefs)prefs={...prefs,...JSON.parse(savedPrefs)};if(innerWidth<=1050){prefs.left=true;prefs.right=true}applyPrefs();try{await storage.init()}catch{}let current=await storage.get('current'),restored=false;if(current){p=C.migrate(current.project);restored=true}else{let old=localStorage.getItem('facebench-v1');if(old){p=C.migrate(JSON.parse(old));restored=true;say('Your v1 design was migrated to v3. Export JSON to keep a backup.')}}loadBlankSetup(restored?p:null);if(!restored)p=C.newFace(savedBlank)}catch(e){say('Saved project could not be loaded: '+e.message+'. Use Open JSON or Fresh start.')}finally{booting=false;render();$('save').textContent='● Ready on device';say('Add a decoration, or choose a starter. New faceplates include magnetic backing.');queueGeometry();if(location.protocol==='file:'){say('Serve this folder for solid geometry and exports: python3 -m http.server 8080. Design editing and JSON remain available.');$('offline').textContent='Local file view · static server required for geometry.'}else if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>$('offline').textContent='Offline cache enabled after first successful load.').catch(()=>$('offline').textContent='Offline cache unavailable; retain a downloaded copy.')}else $('offline').textContent='No service-worker support; keep a local copy.'}})();
